// Generated by vibelang from src/terminalLabels.ts; the migrate flow writes it again with each batch.
function terminalNumber(terminalId) {
    return /^term(?:inal)?-(\d+)(?:-[\da-f]{8}(?:-[\da-f]{4}){3}-[\da-f]{12})?$/i.exec(terminalId)?.[1];
}
export function getTerminalLabel(terminalId) {
    const numericSuffix = terminalNumber(terminalId);
    if (numericSuffix) {
        return `Terminal ${numericSuffix}`;
    }
    return terminalId;
}
export function resolveTerminalSessionLabel(terminalId, summary) {
    const trimmed = summary?.label?.trim();
    if (trimmed && trimmed.length > 0) {
        return trimmed;
    }
    return getTerminalLabel(terminalId);
}
/** Append a UUID when metadata is unavailable to avoid reusing unseen host sessions. */
export function nextTerminalId(existingTerminalIds, uniqueSuffix) {
    const usedNumbers = new Set(existingTerminalIds.map(terminalNumber));
    let nextIndex = 1;
    while (usedNumbers.has(String(nextIndex))) {
        nextIndex += 1;
    }
    return `term-${nextIndex}${uniqueSuffix === undefined ? "" : `-${uniqueSuffix}`}`;
}
